mapper.select:
SELECT ATT_F.SUBSIDIARY_CODE ,TO_CHAR(ATT_F.TIME_AND_ATTENDANCE_DATE, 'DD/MM/YYYY') AS TIME_AND_ATTENDANCE_DATE ,ATT_F.EMPLOYEE_NO ,EM.FULL_NAME_LOCAL AS employee_Name ,EM.ORG_NAME_LOCAL AS organization_Name ,EM.organization_ID AS organization_ID ,tar.shift_type_code AS SHIFT_TYPE_CODE ,(SELECT lgvhr_common_pkg.decode_lookup('LGVHR_SHIFT_TYPE_CODE', tar.shift_type_code, NULL, 'en') AS FROM dual) AS SHIFT_TYPE_NAME ,lgvatt_common_pkg.get_att_code_info(tar.subsidiary_code, tar.time_and_attendance_code, 'NAME') AS attendance_name ,(SELECT lgvatt_common_pkg.get_holiday_flag(tar.subsidiary_code, tar.shift_type_code, tar.time_and_attendance_date) FROM DUAL) AS holiday_flag ,ATT_F.TIME_AND_ATTENDANCE_YYYYMM ,ATT_F.WORK_START_TIME ,ATT_F.TIME_ATTEND_INPUT_REASON_DESC ,ATT_F.CREATION_USER_ID ,ATT_F.CREATION_DATE ,ATT_F.LAST_UPDATE_USER_ID ,ATT_F.LAST_UPDATE_DATE FROM TB_ATT_FLEXIBLE_RESULT_N ATT_F LEFT OUTER JOIN EMP_MASTER EM ON (ATT_F.EMPLOYEE_NO = EM.EMPLOYEE_NUMBER) LEFT OUTER JOIN tb_att_result_n tar ON (tar.employee_no = ATT_F.EMPLOYEE_NO AND TAR.time_and_attendance_date = ATT_F.TIME_AND_ATTENDANCE_DATE) WHERE 1=1 AND ATT_F.SUBSIDIARY_CODE = #{subsidiaryCode}
AND ATT_F.REQUEST_NO = #{requestNo}
AND ATT_F.approval_request_id = #{requestMasterId} ORDER BY ATT_F.REQUEST_SEQ_NO ASC

mapper.update:
	 MERGE /* LGVATT20096.saveFlexibleWorking */ INTO TB_ATT_FLEXIBLE_RESULT_N ATT_F
     USING DUAL
             ON (     
                  	  ATT_F.REQUEST_CODE = #{requestCode}
                  AND ATT_F.APPROVAL_REQUEST_ID = #{approvalRequestId}
                  AND ATT_F.EMPLOYEE_NO = #{employeeNo}
                  AND ATT_F.TIME_AND_ATTENDANCE_DATE = TO_DATE(#{timeAndAttendanceDate}, 'DD/MM/YYYY')
                )
       WHEN MATCHED THEN
            UPDATE SET                         
                    CONFIRM_FLAG						   = 'Y'
                    ,PROGRESS_STATUS_CODE				   = (SELECT status_code FROM lgcom_approval_request_n WHERE request_master_id = ATT_F.approval_request_id AND request_code = ATT_F.request_code) 
                    ,LAST_UPDATE_USER_ID                   = #{sessionUserId}
                    ,LAST_UPDATE_DATE                      = SYSDATE
       WHEN NOT MATCHED THEN
            INSERT 
                   ( 
                    REQUEST_NO
                   ,REQUEST_SEQ_NO 
                   ,REQUEST_DATE
                   ,SUBSIDIARY_CODE
                   ,TIME_AND_ATTENDANCE_DATE
                   ,EMPLOYEE_NO
                   ,TIME_AND_ATTENDANCE_YYYYMM
                   ,WORK_START_TIME
                   ,TIME_ATTEND_INPUT_REASON_DESC
                   ,APPROVAL_REQUEST_ID
                   ,REQUEST_CODE
                   ,PROGRESS_STATUS_CODE
                   ,CONFIRM_FLAG                   
                   ,CREATION_USER_ID
                   ,CREATION_DATE
                   ,LAST_UPDATE_USER_ID
                   ,LAST_UPDATE_DATE
                    )VALUES(
                    #{requestNo}
                   ,sq_tb_att_flexible_id.NEXTVAL
                   ,SYSDATE
                   ,#{subsidiaryCode} 
                   ,TO_DATE(#{timeAndAttendanceDate}, 'DD/MM/YYYY')
                   ,#{employeeNo}
                   ,TO_CHAR(TO_DATE(#{timeAndAttendanceDate}, 'DD/MM/YYYY'), 'YYYYMM')
                   ,#{workStartTime}
                   ,#{timeAttendInputReasonDesc}
                   ,#{approvalRequestId}
                   ,#{requestCode}
                   ,'20'
                   ,'N'                     
                   ,#{sessionUserId}
                   ,SYSDATE
                   ,#{sessionUserId}
                   ,SYSDATE
                       )

	UPDATE TB_ATT_FLEXIBLE_RESULT_N ATT_F
	   SET ATT_F.PROGRESS_STATUS_CODE		= (SELECT status_code FROM lgcom_approval_request_n WHERE request_master_id = ATT_F.approval_request_id AND request_code = ATT_F.request_code) 
          ,ATT_F.LAST_UPDATE_USER_ID      = #{sessionUserId}
          ,ATT_F.LAST_UPDATE_DATE         = SYSDATE
	 WHERE ATT_F.SUBSIDIARY_CODE 			= #{LGVHR_PROJECT_SESSION.subsidiaryCode} 
	   AND ATT_F.REQUEST_CODE 			= #{requestCode}
       AND ATT_F.APPROVAL_REQUEST_ID 		= #{approvalRequestId}

DELETE FROM TB_ATT_FLEXIBLE_RESULT_N ATT_F
 WHERE ATT_F.SUBSIDIARY_CODE = #{subsidiaryCode} 
   AND ATT_F.TIME_AND_ATTENDANCE_DATE = TO_DATE(#{timeAndAttendanceDate}, 'DD/MM/YYYY') 
   AND ATT_F.EMPLOYEE_NO = #{employeeNo}

mapper.select:
SELECT
EM.FULL_NAME_LOCAL AS requestor_info ,(SELECT common_code_name FROM LGCOM_COMMON_CODE_MULTI_LANG_C WHERE code_type_code = 'LGCOM_APPROVAL_REQ_STATUS_CODE' AND language_code = NVL('en','en') AND common_code = ATT_F.PROGRESS_STATUS_CODE) AS status_name ,TO_CHAR(ATT_F.LAST_UPDATE_DATE, 'DD/MM/YYYY') AS request_date , ATT_F.PROGRESS_STATUS_CODE as startus_code
FROM TB_ATT_FLEXIBLE_RESULT_N ATT_F LEFT OUTER JOIN EMP_MASTER EM ON (ATT_F.EMPLOYEE_NO = EM.EMPLOYEE_NUMBER) LEFT OUTER JOIN tb_att_result_n tar ON (tar.employee_no = ATT_F.EMPLOYEE_NO AND TAR.time_and_attendance_date = ATT_F.TIME_AND_ATTENDANCE_DATE) WHERE 1=1 AND ATT_F.TIME_AND_ATTENDANCE_DATE = TO_DATE(#{timeAndAttendanceDate}, 'DD/MM/YYYY') AND ATT_F.EMPLOYEE_NO = #{employeeNo} AND ATT_F.SUBSIDIARY_CODE = #{subsidiaryCode} AND ATT_F.LAST_UPDATE_USER_ID = #{sessionUserId}
